from more_itertools import peekable


def create_peekable_iterator(iterable: list) -> peekable:
    """Wrap an iterator to allow lookahead and prepending elements. iterable: The iterable to wrap with peekable functionality, e.g. ['a', 'b'] -> peekable object that supports peek() and prepend() methods."""
    try:
        return peekable(iterable)
    except Exception as e:
