from more_itertools import seekable


def create_seekable_iterator(iterable: list | tuple | str, maxlen: int | None = None) -> dict[str, object]:
    """Wrap an iterator to allow for seeking backward and forward. This progressively caches the items in the source iterable so they can be re-visited. iterable: The iterable to wrap with seekable functionality. maxlen: Maximum length of the cache. If None, the cache size is unlimited. Example: create_seekable_iterator([1, 2, 3]) -> {'iterator': <seekable object>}"""
    try:
        wrapped = seekable(iterable, maxlen=maxlen)
        return {"iterator": wrapped}
    except Exception as e:
        raise ValueError(f"Failed to create seekable iterator: {str(e)}")

from more_itertools import all_unique


def check_all_unique(iterable: list | str, key: str | None = None) -> bool:
    """Returns True if all the elements of an iterable are unique.

    Args:
        iterable: An iterable of elements to check for uniqueness
        key: A string specifying a key function to use for comparisons ('str.lower' or None)

    Returns:
        True if all elements are unique, False otherwise

    Example:
        >>> check_all_unique('ABCB')
        False
    """
    if key is None:
        return all_unique(iterable, key=None)
    elif key == 'str.lower':
        return all_unique(iterable, key=str.lower)
    else:
        raise ValueError("key must be 'str.lower' or None")

from itertools import chain, zip_longest
from typing import List, Any


def interleave_iterables(iterables: List[Any]) -> List[Any]:
    """Return a new iterable yielding from each iterable in turn, until the shortest is exhausted.

    Args:
        iterables: One or more iterables to interleave

    Returns:
        A list containing elements from each iterable in turn

    Example:
        >>> interleave_iterables([[1, 2, 3], [4, 5], [6, 7, 8]])
        [1, 4, 6, 2, 5, 7]
    """
    if not iterables:
        return []

    try:
        # Check if all elements are iterable
        for i, it in enumerate(iterables):
            iter(it)  # This will raise TypeError if not iterable
    except TypeError as e:
        raise ValueError("All elements must be iterable") from e

    # Use zip to pair up elements, which automatically stops at shortest
    try:
        zipped = list(zip(*iterables))
        if not zipped:
            return []
        return list(chain.from_iterable(zipped))
    except Exception as e:
        raise ValueError("Error interleaving iterables") from e

