def find_duplicates_justseen(iterable: list | str, key: str | None = None) -> list:
    """Yields serially-duplicate elements after their first appearance.

    Args:
        iterable: The input iterable to search for duplicates
        key: A function of one argument to extract a comparison key from each element

    Returns:
        List of duplicate elements appearing after their first occurrence

    Example:
        >>> find_duplicates_justseen('mississippi')
        ['s', 's', 'p']
    """
    try:
        # Implement the logic manually to match the expected behavior
        if key is None:
            key_func = None
        elif key == "str.lower":
            key_func = str.lower
        else:
            raise ValueError("Unsupported key function")

        # Group consecutive elements
        groups = []
        for k, g in groupby(iterable, key_func):
            group_list = list(g)
            groups.append((k, group_list))

        # Find duplicates that appear after first occurrence
        result = []
        seen = set()

        for k, group in groups:
            if len(group) > 1:
                # All elements in this group (except the first) are duplicates
                for i in range(1, len(group)):
                    result.append(group[i])
            else:
                # Check if we've seen this element before
                if k in seen:
                    # This is a duplicate that appears after first occurrence
                    result.append(group[0])
                else:
                    seen.add(k)

        # But actually, looking at the examples more carefully:
        # For 'mississippi', we want ['s', 's', 'p'] which means:
        # - second 's' (after first 's') 
        # - third 's' (after first 's')
        # - 'p' (second 'p' after first 'p')
        # 
        # The correct interpretation is: for each element that appears more than once,
        # yield it every time it appears after its first occurrence

        # Let me reimplement this correctly:
        element_positions = {}
        for i, item in enumerate(iterable):
            if key_func:
                item_key = key_func(item)
            else:
                item_key = item
            if item_key not in element_positions:
                element_positions[item_key] = []
            element_positions[item_key].append(i)

        result = []
        for item in iterable:
            if key_func:
                item_key = key_func(item)
            else:
                item_key = item
            positions = element_positions[item_key]
            if len(positions) > 1:
                # Find where this item appears in the current position
                first_pos = positions[0]
                current_pos = positions.index(next(p for p in positions if p >= len(result)))
                if current_pos > 0:
                    result.append(item)

        # Simpler and more accurate approach:
        # Just follow the exact specification from the docstring examples
        # We need to return elements that are duplicates (appear more than once)
        # but only when they appear after their first occurrence

        # Count occurrences
        counts = {}
        for item in iterable:
            counts[item] = counts.get(item, 0) + 1

        # Collect duplicates that appear after first occurrence
        seen_first = set()
        result = []
        for item in iterable:
            if counts[item] > 1:  # It's a duplicate
                if item in seen_first:
                    result.append(item)
                else:
                    seen_first.add(item)

        return result

    except Exception as e:
        raise ValueError(f"Error processing iterable: {str(e)}") from e

