def _create_predicate_function(predicate_str: str):
    """Create a predicate function from a string representation."""
    # This is a simplified safe evaluator for basic comparisons
    # In a real implementation, you'd want to use a proper expression parser
    if predicate_str.startswith("lambda"):
        # For lambda expressions, we'd need a safer approach
        # This is a limitation of the problem constraints
        raise ValueError("Lambda expressions not supported in this implementation")

    # Handle simple comparison operations
    if "<" in predicate_str and not ("<" in predicate_str and "=" in predicate_str):
        parts = predicate_str.split("<")
        if len(parts) == 2:
            try:
                threshold = float(parts[1].strip())
                return lambda x: x < threshold
            except ValueError:
                pass

    if ">" in predicate_str and not (">" in predicate_str and "=" in predicate_str):
        parts = predicate_str.split(">")
        if len(parts) == 2:
            try:
                threshold = float(parts[1].strip())
                return lambda x: x > threshold
            except ValueError:
                pass

    if "<=" in predicate_str:
        parts = predicate_str.split("<=")
        if len(parts) == 2:
            try:
                threshold = float(parts[1].strip())
                return lambda x: x <= threshold
            except ValueError:
                pass

    if ">=" in predicate_str:
        parts = predicate_str.split(">=")
        if len(parts) == 2:
            try:
                threshold = float(parts[1].strip())
                return lambda x: x >= threshold
            except ValueError:
                pass

    if "==" in predicate_str:
        parts = predicate_str.split("==")
        if len(parts) == 2:
            try:
                threshold = float(parts[1].strip())
                return lambda x: x == threshold
            except ValueError:
                pass

    raise ValueError(f"Unsupported predicate format: {predicate_str}")


def take_while_inclusive(predicate: str, iterable: list) -> list:
    """A variant of :func:`takewhile` that yields one additional element.

    >>> list(takewhile_inclusive(lambda x: x < 5, [1, 4, 6, 4, 1]))
    [1, 4, 6]

    :func:`takewhile` would return ``[1, 4]``.

    Args:
        predicate: A string representation of a predicate function that takes one argument and returns a boolean
        iterable: An array of elements to process

    Returns:
        A list of elements from the iterable, including one additional element after the predicate fails
    """
    try:
        pred_func = _create_predicate_function(predicate)
        result = list(takewhile_inclusive(pred_func, iterable))
        return result
    except Exception as e:
        raise ValueError(f"Invalid predicate expression: {predicate}") from e

from collections import defaultdict
from typing import Any, Iterable, Optional, Dict


def map_and_reduce(
    iterable: Iterable[Any],
    keyfunc: object,
    valuefunc: Optional[object] = None,
    reducefunc: Optional[object] = None,
) -> Dict[str, Any]:
    """Return a dictionary that maps items in *iterable* to categories defined by *keyfunc*, transforms them with *valuefunc*, and reduces them with *reducefunc*.

    Args:
        iterable: The input iterable to process
        keyfunc: Function that maps items to categories
        valuefunc: Function that transforms items before grouping (optional)
        reducefunc: Function that summarizes grouped items (optional)

    Example:
        >>> keyfunc = lambda x: x.upper()
        >>> map_and_reduce('abbccc', keyfunc)
        {'A': ['a'], 'B': ['b', 'b'], 'C': ['c', 'c', 'c']}
    """
    try:
        ret = defaultdict(list)

        if valuefunc is None:
            for item in iterable:
                key = keyfunc(item)
                ret[key].append(item)
        else:
            for item in iterable:
                key = keyfunc(item)
                value = valuefunc(item)
                ret[key].append(value)

        if reducefunc is not None:
            for key, value_list in ret.items():
                ret[key] = reducefunc(value_list)

        ret.default_factory = None
        return dict(ret)
    except Exception as e:
        raise ValueError(f"Error in map_and_reduce: {str(e)}") from e

from itertools import chain, repeat
from typing import List, Union


def repeat_sequence(iterable: List[Union[str, int, float, bool]], n: int) -> List[Union[str, int, float, bool]]:
    """Returns the sequence elements n times. iterable: The sequence of elements to repeat, n: Number of times to repeat the sequence"""
    if n < 0:
        raise ValueError("n must be non-negative")

    try:
        result = list(chain.from_iterable(repeat(tuple(iterable), n)))
        return result
    except Exception as e:
        raise ValueError(f"Error processing sequence: {str(e)}")

from itertools import zip_longest
from typing import Any, List, Union


def group_elements(iterable: List[Any], n: int, incomplete: str = 'fill', fillvalue: Any = None) -> List[tuple]:
    """Group elements from *iterable* into fixed-length groups of length *n*.

    Args:
        iterable: The iterable to group elements from
        n: The fixed-length of each group
        incomplete: How to handle iterables whose length is not a multiple of n
        fillvalue: The value to use for filling incomplete groups when incomplete='fill'

    Returns:
        List of tuples containing grouped elements

    Example:
        >>> group_elements(['A', 'B', 'C', 'D', 'E', 'F'], 3)
        [('A', 'B', 'C'), ('D', 'E', 'F')]
    """
    if n <= 0:
        raise ValueError("n must be positive")

    if incomplete not in ('fill', 'strict', 'ignore'):
        raise ValueError("incomplete must be 'fill', 'strict', or 'ignore'")

    iterators = [iter(iterable)] * n

    try:
        if incomplete == 'fill':
            return list(zip_longest(*iterators, fillvalue=fillvalue))
        elif incomplete == 'strict':
            return list(zip(*iterators, strict=True))
        else:  # incomplete == 'ignore'
            return list(zip(*iterators))
    except ValueError as e:
        if "zip() argument 1 is longer than the rest" in str(e):
            raise ValueError("Iterable length is not a multiple of n and incomplete='strict'")
        raise e

from more_itertools import batched as _batched


def batch_elements(iterable: list | str | tuple, n: int) -> list[list | str | tuple]:
    """Batch elements of an iterable into fixed-length chunks. iterable: The iterable to batch into fixed-length chunks, e.g. [1,2,3,4], 2 -> [[1,2], [3,4]]. n: The fixed length of each chunk, e.g. 2."""
    if not isinstance(iterable, (list, str, tuple)):
        raise ValueError("iterable must be a list, string, or tuple")
    if not isinstance(n, int) or n <= 0:
        raise ValueError("n must be a positive integer")

    try:
        result = list(_batched(iterable, n, strict=False))
        return [list(chunk) if isinstance(chunk, tuple) else chunk for chunk in result]
    except Exception as e:
        raise ValueError(f"Error batching elements: {str(e)}")

from more_itertools import quantify


def count_matches(iterable: list, pred: str | None = None) -> int:
    """Count how many times a predicate is true in an iterable.

    Args:
        iterable: The iterable to check
        pred: The predicate function as a string representation

    Returns:
        The count of items for which the predicate is true

    Example:
        >>> count_matches([True, False, True])
        2
    """
    try:
        if pred is None:
            return quantify(iterable)
        elif pred == "bool":
            return quantify(iterable, pred=bool)
        elif pred == "len":
            return quantify(iterable, pred=len)
        else:
            raise ValueError(f"Unsupported predicate: {pred}")
    except Exception as e:
        raise ValueError(f"Invalid predicate: {pred}") from e
